HTML='''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jarvis v223</title><style>body{margin:0;background:#07111f;color:#edf5ff;font:16px system-ui}.w{max-width:1180px;margin:auto;padding:28px}.top,.row{display:flex;gap:12px;align-items:center;justify-content:space-between}.card{background:#101d30;border:1px solid #29405f;border-radius:18px;padding:22px;margin:16px 0}textarea,input{box-sizing:border-box;width:100%;background:#07111f;color:white;border:1px solid #395474;border-radius:12px;padding:14px}button{background:#3985ff;color:white;border:0;border-radius:11px;padding:12px 16px;font-weight:700}.grid{display:grid;grid-template-columns:2fr 1fr;gap:16px}.muted{color:#9bb0ca}.ok{color:#47d9a2}.bad{color:#ff7185}@media(max-width:800px){.grid{grid-template-columns:1fr}.row{flex-wrap:wrap}}</style></head><body><div class=w><div class=top><div><h1>JARVIS v223</h1><div class=muted>Autonomous Operations Agent</div></div><b id=rt>Connecting...</b></div><div id=b class=card>Starting backend...</div><div id=login class=card><h2>Owner Access</h2><input id=p type=password placeholder="Owner password"><p><button onclick=login()>Open Jarvis</button></p><div id=e class=bad></div></div><div id=app style="display:none" class=grid><div><div class=card><h2>Give Jarvis an objective</h2><textarea id=c rows=4></textarea><p class=row><button onclick=send()>Start objective</button><button onclick=testm()>Test AI model</button><button onclick=testc()>Test GitHub + Render</button></p><div id=r class=muted></div></div><div class=card><h2>Objectives</h2><div id=o></div></div></div><div><div class=card><h2>Runtime</h2><div id=s></div></div><div class=card><h2>Live activity</h2><div id=a></div></div></div></div></div><script>const $=x=>document.getElementById(x);async function api(u,o={}){let x=await fetch(u,{...o,cache:'no-store'});let d=await x.json();if(x.status==401){$('login').style.display='block';$('app').style.display='none';throw Error(d.detail||'Owner login required')}if(!x.ok)throw Error(d.detail||d.error||('HTTP '+x.status));return d}async function boot(){try{let d=await api('/client/bootstrap');$('b').textContent='Jarvis '+d.version+' backend online.';if(d.authenticated){$('login').style.display='none';$('app').style.display='grid';poll()}else $('rt').textContent='Owner login required'}catch(e){$('b').textContent='Backend connection failed: '+e.message}}async function login(){try{await api('/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({password:$('p').value})});$('p').value='';$('login').style.display='none';$('app').style.display='grid';poll()}catch(e){$('e').textContent=e.message}}async function send(){let text=$('c').value.trim();if(!text)return;try{let d=await api('/agent/v223/command',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text,request_id:crypto.randomUUID()})});$('r').textContent=d.message;$('c').value='';poll()}catch(e){$('r').textContent=e.message}}async function testm(){try{let d=await api('/model/test',{method:'POST'});$('r').textContent=d.ok?'AI model connected: '+d.active_model:'AI model failed: '+d.last_error}catch(e){$('r').textContent=e.message}}async function testc(){try{let d=await api('/connections/test',{method:'POST'});$('r').textContent='GitHub '+d.github.status+'; Render '+d.render.status}catch(e){$('r').textContent=e.message}}async function poll(){try{let s=await api('/agent/status');$('rt').textContent=s.worker_alive?'Agent online':'Supervisor recovering';$('s').textContent=s.running+' running · '+s.queued+' queued · '+s.blocked+' blocked · '+s.completed+' complete';let o=await api('/agent/objectives');$('o').innerHTML=o.map(x=>'<p><b>#'+x.id+' '+x.title+'</b> · '+x.state+' · cycle '+x.step+'/'+x.max_steps+'</p>').join('')||'No objectives';let a=await api('/agent/activity');$('a').innerHTML=a.slice(0,20).map(x=>'<p><b>'+x.event+'</b><br><span class=muted>'+String(x.detail||'').slice(0,500)+'</span></p>').join('')}catch(e){$('rt').textContent='Status delayed'}setTimeout(poll,5000)}boot()</script></body></html>'''
